INSERT INTO public.template_catalogue(id,kind,content_version,payload) VALUES
('kinra-gym-foundations','training',1,'{"en":{"name":"Gym foundations · 2 days","description":"Two straightforward full-body sessions with machines and a dumbbell squat. Alternate A and B with at least one rest day.\n\nRepeat the listed week. Begin at the low end of each rep range with 3–4 reps in reserve (RPE 6–7). Add one rep per set when controlled; after every set reaches the top, increase the smallest available load and return to the low end. Do not increase load and sets together. If recovery or form worsens, repeat the previous week or remove one set.\n\nAn original general adult example, not an individually assessed prescription. Review exercises and equipment first. Start with easy practice sets; stop for pain or feeling unwell. Schedule rest between hard sessions. Adjust or seek qualified guidance when health, pregnancy or injury affects exercise.","weeks":6,"days":[{"title":"A · Full body","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0266-flat-machine-chest-press-wide-grip","name":"Flat Machine Chest Press (Wide Grip)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0582-seated-leg-curl-machine","name":"Seated Leg Curl (Machine)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"6–10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."}]},{"title":"B · Full body","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0282-glute-bridge-most-straznjice","name":"Glute Bridge (Most stražnjice)","sets":2,"reps":"10–15","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0679-standing-calf-raise-machine","name":"Standing Calf Raise (Machine)","sets":2,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."}]}]},"bs":{"name":"Osnove teretane · 2 dana","description":"Dva jednostavna treninga cijelog tijela uz sprave i čučanj s bučicom. Smjenjujte A i B uz barem dan odmora.\n\nPonavljajte prikazanu sedmicu. Počnite donjim brojem ponavljanja uz 3–4 ponavljanja u rezervi (RPE 6–7). Dodajte po jedno kontrolisano ponavljanje u seriji; kada sve serije dostignu gornju granicu, dodajte najmanje dostupno opterećenje i vratite se donjoj. Ne povećavajte istovremeno opterećenje i broj serija. Ako oporavak ili tehnika oslabe, ponovite prethodnu sedmicu ili uklonite jednu seriju.\n\nOriginalni opći primjer za odrasle, bez individualne procjene. Prvo pregledajte vježbe i opremu. Počnite laganim probnim serijama; stanite kod bola ili lošeg osjećaja. Ostavite odmor između težih treninga. Prilagodite plan ili zatražite stručni savjet ako zdravlje, trudnoća ili povreda utiču na vježbanje.","weeks":6,"days":[{"title":"A · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0266-flat-machine-chest-press-wide-grip","name":"Flat Machine Chest Press (Wide Grip)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0582-seated-leg-curl-machine","name":"Seated Leg Curl (Machine)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"6–10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."}]},{"title":"B · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0282-glute-bridge-most-straznjice","name":"Glute Bridge (Most stražnjice)","sets":2,"reps":"10–15","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0679-standing-calf-raise-machine","name":"Standing Calf Raise (Machine)","sets":2,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."}]}]},"de":{"name":"Studio-Grundlagen · 2 Tage","description":"Zwei einfache Ganzkörpereinheiten mit Geräten und einer Kurzhantel-Kniebeuge. A und B mit mindestens einem Ruhetag abwechseln.\n\nDie angegebene Woche wiederholen. Am unteren Ende des Wiederholungsbereichs mit 3–4 Wiederholungen Reserve (RPE 6–7) beginnen. Bei guter Kontrolle eine Wiederholung pro Satz ergänzen; erreichen alle Sätze die Obergrenze, das kleinste verfügbare Gewicht hinzufügen und unten beginnen. Gewicht und Satzzahl nicht gleichzeitig erhöhen. Bei schlechterer Erholung oder Technik die Vorwoche wiederholen oder einen Satz streichen.\n\nEin eigenes allgemeines Beispiel für Erwachsene ohne individuelle Untersuchung. Übungen und Geräte zuerst prüfen. Mit leichten Übungssätzen beginnen; bei Schmerzen oder Unwohlsein stoppen. Zwischen schweren Einheiten Erholung einplanen. Bei gesundheitlichen Einschränkungen, Schwangerschaft oder Verletzung anpassen oder fachlichen Rat einholen.","weeks":6,"days":[{"title":"A · Ganzkörper","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0266-flat-machine-chest-press-wide-grip","name":"Flat Machine Chest Press (Wide Grip)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0582-seated-leg-curl-machine","name":"Seated Leg Curl (Machine)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"6–10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."}]},{"title":"B · Ganzkörper","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0282-glute-bridge-most-straznjice","name":"Glute Bridge (Most stražnjice)","sets":2,"reps":"10–15","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0679-standing-calf-raise-machine","name":"Standing Calf Raise (Machine)","sets":2,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."}]}]}}'::jsonb),
('kinra-home-basics','training',1,'{"en":{"name":"Home basics · 2 days","description":"No-equipment squat, push and trunk practice for a small space. This starting plan has limited pulling work; add a reviewed row option when equipment is available.\n\nRepeat the week with a rest day between sessions. Add one controlled rep per set up to the upper limit. Then use a slightly harder movement variation only after reviewing it, and restart at the lower limit. Keep 2–4 reps in reserve; extra speed is not progression.\n\nAn original general adult example, not an individually assessed prescription. Review exercises and equipment first. Start with easy practice sets; stop for pain or feeling unwell. Schedule rest between hard sessions. Adjust or seek qualified guidance when health, pregnancy or injury affects exercise.","weeks":4,"days":[{"title":"A · Full body","exercises":[{"catalogue_id":"exercise-0071-bodyweight-squat-cucanj-s-tjelesnom-tezinom","name":"Bodyweight Squat (Čučanj s tjelesnom težinom)","sets":2,"reps":"8–12","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0364-knee-push-up-skleka-s-koljenima","name":"Knee Push-Up (Skleka s koljenima)","sets":2,"reps":"6–10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0282-glute-bridge-most-straznjice","name":"Glute Bridge (Most stražnjice)","sets":2,"reps":"10–15","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0068-bird-dog-pas-koji-trazi-prticicu","name":"Bird Dog (Pas koji traži prtičicu)","sets":2,"reps":"6–8","rest_seconds":45,"rpe":5,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."}]},{"title":"B · Full body","exercises":[{"catalogue_id":"exercise-0542-reverse-lunge-iskorak-unazad","name":"Reverse Lunge (Iskorak unazad)","sets":2,"reps":"6–10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."},{"catalogue_id":"exercise-0760-wall-push-up-plus-skleka-uz-zid-s-protrakcijom-serratus","name":"Wall Push-Up Plus (Skleka uz zid s protrakcijom — serratus)","sets":2,"reps":"8–12","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0633-single-leg-glute-bridge-jednonozni-most","name":"Single-Leg Glute Bridge (Jednonožni most)","sets":2,"reps":"6–10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"6–10","rest_seconds":45,"rpe":5,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."}]}]},"bs":{"name":"Kućne osnove · 2 dana","description":"Čučanj, potisak i trup bez opreme u malom prostoru. Plan ima malo povlačenja; dodajte pregledanu varijantu veslanja kada imate opremu.\n\nPonavljajte sedmicu uz dan odmora između treninga. Dodajte po jedno kontrolisano ponavljanje do gornje granice. Zatim, tek nakon pregleda, odaberite malo težu varijantu i počnite donjim brojem. Zadržite 2–4 ponavljanja u rezervi; veća brzina nije napredak.\n\nOriginalni opći primjer za odrasle, bez individualne procjene. Prvo pregledajte vježbe i opremu. Počnite laganim probnim serijama; stanite kod bola ili lošeg osjećaja. Ostavite odmor između težih treninga. Prilagodite plan ili zatražite stručni savjet ako zdravlje, trudnoća ili povreda utiču na vježbanje.","weeks":4,"days":[{"title":"A · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0071-bodyweight-squat-cucanj-s-tjelesnom-tezinom","name":"Bodyweight Squat (Čučanj s tjelesnom težinom)","sets":2,"reps":"8–12","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0364-knee-push-up-skleka-s-koljenima","name":"Knee Push-Up (Skleka s koljenima)","sets":2,"reps":"6–10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0282-glute-bridge-most-straznjice","name":"Glute Bridge (Most stražnjice)","sets":2,"reps":"10–15","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0068-bird-dog-pas-koji-trazi-prticicu","name":"Bird Dog (Pas koji traži prtičicu)","sets":2,"reps":"6–8","rest_seconds":45,"rpe":5,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."}]},{"title":"B · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0542-reverse-lunge-iskorak-unazad","name":"Reverse Lunge (Iskorak unazad)","sets":2,"reps":"6–10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."},{"catalogue_id":"exercise-0760-wall-push-up-plus-skleka-uz-zid-s-protrakcijom-serratus","name":"Wall Push-Up Plus (Skleka uz zid s protrakcijom — serratus)","sets":2,"reps":"8–12","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0633-single-leg-glute-bridge-jednonozni-most","name":"Single-Leg Glute Bridge (Jednonožni most)","sets":2,"reps":"6–10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"6–10","rest_seconds":45,"rpe":5,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."}]}]},"de":{"name":"Zuhause-Grundlagen · 2 Tage","description":"Kniebeuge, Drücken und Rumpfpraxis ohne Geräte auf kleinem Raum. Zugübungen sind begrenzt; bei verfügbarer Ausrüstung eine geprüfte Ruderübung ergänzen.\n\nDie Woche mit einem Ruhetag zwischen Einheiten wiederholen. Kontrollierte Wiederholungen bis zur Obergrenze ergänzen. Danach erst nach Prüfung eine etwas schwierigere Variante wählen und unten beginnen. 2–4 Wiederholungen Reserve lassen; höheres Tempo ist kein Fortschrittskriterium.\n\nEin eigenes allgemeines Beispiel für Erwachsene ohne individuelle Untersuchung. Übungen und Geräte zuerst prüfen. Mit leichten Übungssätzen beginnen; bei Schmerzen oder Unwohlsein stoppen. Zwischen schweren Einheiten Erholung einplanen. Bei gesundheitlichen Einschränkungen, Schwangerschaft oder Verletzung anpassen oder fachlichen Rat einholen.","weeks":4,"days":[{"title":"A · Ganzkörper","exercises":[{"catalogue_id":"exercise-0071-bodyweight-squat-cucanj-s-tjelesnom-tezinom","name":"Bodyweight Squat (Čučanj s tjelesnom težinom)","sets":2,"reps":"8–12","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0364-knee-push-up-skleka-s-koljenima","name":"Knee Push-Up (Skleka s koljenima)","sets":2,"reps":"6–10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0282-glute-bridge-most-straznjice","name":"Glute Bridge (Most stražnjice)","sets":2,"reps":"10–15","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0068-bird-dog-pas-koji-trazi-prticicu","name":"Bird Dog (Pas koji traži prtičicu)","sets":2,"reps":"6–8","rest_seconds":45,"rpe":5,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."}]},{"title":"B · Ganzkörper","exercises":[{"catalogue_id":"exercise-0542-reverse-lunge-iskorak-unazad","name":"Reverse Lunge (Iskorak unazad)","sets":2,"reps":"6–10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."},{"catalogue_id":"exercise-0760-wall-push-up-plus-skleka-uz-zid-s-protrakcijom-serratus","name":"Wall Push-Up Plus (Skleka uz zid s protrakcijom — serratus)","sets":2,"reps":"8–12","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0633-single-leg-glute-bridge-jednonozni-most","name":"Single-Leg Glute Bridge (Jednonožni most)","sets":2,"reps":"6–10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"6–10","rest_seconds":45,"rpe":5,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."}]}]}}'::jsonb),
('kinra-dumbbell-full-body','training',1,'{"en":{"name":"Dumbbell full body · 3 days","description":"Three alternating sessions with a pair of dumbbells and a stable bench. Allow a rest day between sessions.\n\nRepeat the listed week. Begin at the low end of each rep range with 3–4 reps in reserve (RPE 6–7). Add one rep per set when controlled; after every set reaches the top, increase the smallest available load and return to the low end. Do not increase load and sets together. If recovery or form worsens, repeat the previous week or remove one set.\n\nAn original general adult example, not an individually assessed prescription. Review exercises and equipment first. Start with easy practice sets; stop for pain or feeling unwell. Schedule rest between hard sessions. Adjust or seek qualified guidance when health, pregnancy or injury affects exercise.","weeks":6,"days":[{"title":"A · Full body","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0628-single-arm-dumbbell-row-jednoruko-veslanje-bucicom","name":"Single-Arm Dumbbell Row (Jednoruko veslanje bučicom)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."},{"catalogue_id":"exercise-0364-knee-push-up-skleka-s-koljenima","name":"Knee Push-Up (Skleka s koljenima)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0224-dumbbell-glute-bridge","name":"Dumbbell Glute Bridge","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"8","rest_seconds":45,"rpe":6,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."}]},{"title":"B · Full body","exercises":[{"catalogue_id":"exercise-0619-single-leg-deadlift","name":"Single Leg Deadlift","sets":2,"reps":"8–10","rest_seconds":90,"rpe":7,"section":"main","notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0628-single-arm-dumbbell-row-jednoruko-veslanje-bucicom","name":"Single-Arm Dumbbell Row (Jednoruko veslanje bučicom)","sets":3,"reps":"10–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."},{"catalogue_id":"exercise-0228-dumbbell-lunges-iskoraci-s-bucicama","name":"Dumbbell Lunges (Iskoraci s bučicama)","sets":2,"reps":"8–10","rest_seconds":90,"rpe":7,"section":"main","notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."},{"catalogue_id":"exercise-0218-dumbbell-biceps-curl","name":"Dumbbell Biceps Curl","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."}]},{"title":"C · Full body","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":3,"reps":"10–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0628-single-arm-dumbbell-row-jednoruko-veslanje-bucicom","name":"Single-Arm Dumbbell Row (Jednoruko veslanje bučicom)","sets":3,"reps":"10–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."},{"catalogue_id":"exercise-0507-push-up-skleka","name":"Push-Up (Skleka)","sets":3,"reps":"6–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0224-dumbbell-glute-bridge","name":"Dumbbell Glute Bridge","sets":3,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0238-dumbbell-standing-calf-raise","name":"Dumbbell Standing Calf Raise","sets":2,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."}]}]},"bs":{"name":"Cijelo tijelo s bučicama · 3 dana","description":"Tri različita treninga uz par bučica i stabilnu klupu. Ostavite dan odmora između treninga.\n\nPonavljajte prikazanu sedmicu. Počnite donjim brojem ponavljanja uz 3–4 ponavljanja u rezervi (RPE 6–7). Dodajte po jedno kontrolisano ponavljanje u seriji; kada sve serije dostignu gornju granicu, dodajte najmanje dostupno opterećenje i vratite se donjoj. Ne povećavajte istovremeno opterećenje i broj serija. Ako oporavak ili tehnika oslabe, ponovite prethodnu sedmicu ili uklonite jednu seriju.\n\nOriginalni opći primjer za odrasle, bez individualne procjene. Prvo pregledajte vježbe i opremu. Počnite laganim probnim serijama; stanite kod bola ili lošeg osjećaja. Ostavite odmor između težih treninga. Prilagodite plan ili zatražite stručni savjet ako zdravlje, trudnoća ili povreda utiču na vježbanje.","weeks":6,"days":[{"title":"A · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0628-single-arm-dumbbell-row-jednoruko-veslanje-bucicom","name":"Single-Arm Dumbbell Row (Jednoruko veslanje bučicom)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."},{"catalogue_id":"exercise-0364-knee-push-up-skleka-s-koljenima","name":"Knee Push-Up (Skleka s koljenima)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0224-dumbbell-glute-bridge","name":"Dumbbell Glute Bridge","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"8","rest_seconds":45,"rpe":6,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."}]},{"title":"B · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0619-single-leg-deadlift","name":"Single Leg Deadlift","sets":2,"reps":"8–10","rest_seconds":90,"rpe":7,"section":"main","notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0628-single-arm-dumbbell-row-jednoruko-veslanje-bucicom","name":"Single-Arm Dumbbell Row (Jednoruko veslanje bučicom)","sets":3,"reps":"10–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."},{"catalogue_id":"exercise-0228-dumbbell-lunges-iskoraci-s-bucicama","name":"Dumbbell Lunges (Iskoraci s bučicama)","sets":2,"reps":"8–10","rest_seconds":90,"rpe":7,"section":"main","notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."},{"catalogue_id":"exercise-0218-dumbbell-biceps-curl","name":"Dumbbell Biceps Curl","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."}]},{"title":"C · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":3,"reps":"10–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0628-single-arm-dumbbell-row-jednoruko-veslanje-bucicom","name":"Single-Arm Dumbbell Row (Jednoruko veslanje bučicom)","sets":3,"reps":"10–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."},{"catalogue_id":"exercise-0507-push-up-skleka","name":"Push-Up (Skleka)","sets":3,"reps":"6–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0224-dumbbell-glute-bridge","name":"Dumbbell Glute Bridge","sets":3,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0238-dumbbell-standing-calf-raise","name":"Dumbbell Standing Calf Raise","sets":2,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."}]}]},"de":{"name":"Kurzhantel-Ganzkörper · 3 Tage","description":"Drei wechselnde Einheiten mit zwei Kurzhanteln und stabiler Bank. Einen Ruhetag zwischen Einheiten einplanen.\n\nDie angegebene Woche wiederholen. Am unteren Ende des Wiederholungsbereichs mit 3–4 Wiederholungen Reserve (RPE 6–7) beginnen. Bei guter Kontrolle eine Wiederholung pro Satz ergänzen; erreichen alle Sätze die Obergrenze, das kleinste verfügbare Gewicht hinzufügen und unten beginnen. Gewicht und Satzzahl nicht gleichzeitig erhöhen. Bei schlechterer Erholung oder Technik die Vorwoche wiederholen oder einen Satz streichen.\n\nEin eigenes allgemeines Beispiel für Erwachsene ohne individuelle Untersuchung. Übungen und Geräte zuerst prüfen. Mit leichten Übungssätzen beginnen; bei Schmerzen oder Unwohlsein stoppen. Zwischen schweren Einheiten Erholung einplanen. Bei gesundheitlichen Einschränkungen, Schwangerschaft oder Verletzung anpassen oder fachlichen Rat einholen.","weeks":6,"days":[{"title":"A · Ganzkörper","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0628-single-arm-dumbbell-row-jednoruko-veslanje-bucicom","name":"Single-Arm Dumbbell Row (Jednoruko veslanje bučicom)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."},{"catalogue_id":"exercise-0364-knee-push-up-skleka-s-koljenima","name":"Knee Push-Up (Skleka s koljenima)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0224-dumbbell-glute-bridge","name":"Dumbbell Glute Bridge","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"8","rest_seconds":45,"rpe":6,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."}]},{"title":"B · Ganzkörper","exercises":[{"catalogue_id":"exercise-0619-single-leg-deadlift","name":"Single Leg Deadlift","sets":2,"reps":"8–10","rest_seconds":90,"rpe":7,"section":"main","notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0628-single-arm-dumbbell-row-jednoruko-veslanje-bucicom","name":"Single-Arm Dumbbell Row (Jednoruko veslanje bučicom)","sets":3,"reps":"10–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."},{"catalogue_id":"exercise-0228-dumbbell-lunges-iskoraci-s-bucicama","name":"Dumbbell Lunges (Iskoraci s bučicama)","sets":2,"reps":"8–10","rest_seconds":90,"rpe":7,"section":"main","notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."},{"catalogue_id":"exercise-0218-dumbbell-biceps-curl","name":"Dumbbell Biceps Curl","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."}]},{"title":"C · Ganzkörper","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":3,"reps":"10–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0628-single-arm-dumbbell-row-jednoruko-veslanje-bucicom","name":"Single-Arm Dumbbell Row (Jednoruko veslanje bučicom)","sets":3,"reps":"10–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."},{"catalogue_id":"exercise-0507-push-up-skleka","name":"Push-Up (Skleka)","sets":3,"reps":"6–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0224-dumbbell-glute-bridge","name":"Dumbbell Glute Bridge","sets":3,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0238-dumbbell-standing-calf-raise","name":"Dumbbell Standing Calf Raise","sets":2,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."}]}]}}'::jsonb),
('kinra-upper-lower','training',1,'{"en":{"name":"Upper / lower · 4 days","description":"A balanced four-session split: upper, lower, rest, upper, lower. A repeatable next step after full-body training.\n\nRepeat the listed week. Begin at the low end of each rep range with 3–4 reps in reserve (RPE 6–7). Add one rep per set when controlled; after every set reaches the top, increase the smallest available load and return to the low end. Do not increase load and sets together. If recovery or form worsens, repeat the previous week or remove one set.\n\nAn original general adult example, not an individually assessed prescription. Review exercises and equipment first. Start with easy practice sets; stop for pain or feeling unwell. Schedule rest between hard sessions. Adjust or seek qualified guidance when health, pregnancy or injury affects exercise.","weeks":8,"days":[{"title":"A · Upper","exercises":[{"catalogue_id":"exercise-0060-bench-press-potisak-s-ravne-klupe","name":"Bench Press (Potisak s ravne klupe)","sets":3,"reps":"6–10","rest_seconds":150,"rpe":7,"section":"main","notes":"Use a rack with correctly set safeties or a competent spotter where needed. Warm up with lighter practice sets before the working sets."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0227-dumbbell-lateral-raise","name":"Dumbbell Lateral Raise","sets":2,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0554-rope-triceps-pushdown","name":"Rope Triceps Pushdown","sets":2,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."}]},{"title":"A · Lower","exercises":[{"catalogue_id":"exercise-0035-back-squat-cucanj-sa-sipkom","name":"Back Squat (Čučanj sa šipkom)","sets":3,"reps":"6–10","rest_seconds":180,"rpe":7,"section":"main","notes":"Use a rack with correctly set safeties or a competent spotter where needed. Warm up with lighter practice sets before the working sets."},{"catalogue_id":"exercise-0549-romanian-deadlift","name":"Romanian Deadlift","sets":3,"reps":"8–10","rest_seconds":150,"rpe":7,"section":"main","notes":"Use a rack with correctly set safeties or a competent spotter where needed. Warm up with lighter practice sets before the working sets."},{"catalogue_id":"exercise-0392-leg-extension-machine","name":"Leg Extension (Machine)","sets":2,"reps":"10–15","rest_seconds":75,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0575-seated-calf-raise","name":"Seated Calf Raise","sets":3,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"8–10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."}]},{"title":"B · Upper","exercises":[{"catalogue_id":"exercise-0330-incline-bench-press-kosi-potisak-gornji-dio-prsa","name":"Incline Bench Press (Kosi potisak — gornji dio prsa)","sets":3,"reps":"8–12","rest_seconds":120,"rpe":7,"section":"main","notes":"Use a rack with correctly set safeties or a competent spotter where needed. Warm up with lighter practice sets before the working sets."},{"catalogue_id":"exercise-0152-chest-supported-row-veslanje-s-osloncem-na-prsa","name":"Chest Supported Row (Veslanje s osloncem na prsa)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0227-dumbbell-lateral-raise","name":"Dumbbell Lateral Raise","sets":2,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0218-dumbbell-biceps-curl","name":"Dumbbell Biceps Curl","sets":2,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."}]},{"title":"B · Lower","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":3,"reps":"10–12","rest_seconds":120,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0582-seated-leg-curl-machine","name":"Seated Leg Curl (Machine)","sets":3,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0094-bulgarian-split-squat","name":"Bulgarian Split Squat","sets":2,"reps":"8–10","rest_seconds":90,"rpe":7,"section":"main","notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."},{"catalogue_id":"exercise-0679-standing-calf-raise-machine","name":"Standing Calf Raise (Machine)","sets":3,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0068-bird-dog-pas-koji-trazi-prticicu","name":"Bird Dog (Pas koji traži prtičicu)","sets":2,"reps":"8","rest_seconds":45,"rpe":6,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."}]}]},"bs":{"name":"Gornji / donji dio · 4 dana","description":"Uravnotežena podjela: gornji dio, donji dio, odmor, gornji dio, donji dio. Sljedeći korak nakon treninga cijelog tijela.\n\nPonavljajte prikazanu sedmicu. Počnite donjim brojem ponavljanja uz 3–4 ponavljanja u rezervi (RPE 6–7). Dodajte po jedno kontrolisano ponavljanje u seriji; kada sve serije dostignu gornju granicu, dodajte najmanje dostupno opterećenje i vratite se donjoj. Ne povećavajte istovremeno opterećenje i broj serija. Ako oporavak ili tehnika oslabe, ponovite prethodnu sedmicu ili uklonite jednu seriju.\n\nOriginalni opći primjer za odrasle, bez individualne procjene. Prvo pregledajte vježbe i opremu. Počnite laganim probnim serijama; stanite kod bola ili lošeg osjećaja. Ostavite odmor između težih treninga. Prilagodite plan ili zatražite stručni savjet ako zdravlje, trudnoća ili povreda utiču na vježbanje.","weeks":8,"days":[{"title":"A · Gornji dio","exercises":[{"catalogue_id":"exercise-0060-bench-press-potisak-s-ravne-klupe","name":"Bench Press (Potisak s ravne klupe)","sets":3,"reps":"6–10","rest_seconds":150,"rpe":7,"section":"main","notes":"Po potrebi koristite stalak s pravilno postavljenim osiguračima ili sposobnog pomagača. Prije radnih serija uradite lakše probne serije."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0227-dumbbell-lateral-raise","name":"Dumbbell Lateral Raise","sets":2,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0554-rope-triceps-pushdown","name":"Rope Triceps Pushdown","sets":2,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."}]},{"title":"A · Donji dio","exercises":[{"catalogue_id":"exercise-0035-back-squat-cucanj-sa-sipkom","name":"Back Squat (Čučanj sa šipkom)","sets":3,"reps":"6–10","rest_seconds":180,"rpe":7,"section":"main","notes":"Po potrebi koristite stalak s pravilno postavljenim osiguračima ili sposobnog pomagača. Prije radnih serija uradite lakše probne serije."},{"catalogue_id":"exercise-0549-romanian-deadlift","name":"Romanian Deadlift","sets":3,"reps":"8–10","rest_seconds":150,"rpe":7,"section":"main","notes":"Po potrebi koristite stalak s pravilno postavljenim osiguračima ili sposobnog pomagača. Prije radnih serija uradite lakše probne serije."},{"catalogue_id":"exercise-0392-leg-extension-machine","name":"Leg Extension (Machine)","sets":2,"reps":"10–15","rest_seconds":75,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0575-seated-calf-raise","name":"Seated Calf Raise","sets":3,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"8–10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."}]},{"title":"B · Gornji dio","exercises":[{"catalogue_id":"exercise-0330-incline-bench-press-kosi-potisak-gornji-dio-prsa","name":"Incline Bench Press (Kosi potisak — gornji dio prsa)","sets":3,"reps":"8–12","rest_seconds":120,"rpe":7,"section":"main","notes":"Po potrebi koristite stalak s pravilno postavljenim osiguračima ili sposobnog pomagača. Prije radnih serija uradite lakše probne serije."},{"catalogue_id":"exercise-0152-chest-supported-row-veslanje-s-osloncem-na-prsa","name":"Chest Supported Row (Veslanje s osloncem na prsa)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0227-dumbbell-lateral-raise","name":"Dumbbell Lateral Raise","sets":2,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0218-dumbbell-biceps-curl","name":"Dumbbell Biceps Curl","sets":2,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."}]},{"title":"B · Donji dio","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":3,"reps":"10–12","rest_seconds":120,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0582-seated-leg-curl-machine","name":"Seated Leg Curl (Machine)","sets":3,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0094-bulgarian-split-squat","name":"Bulgarian Split Squat","sets":2,"reps":"8–10","rest_seconds":90,"rpe":7,"section":"main","notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."},{"catalogue_id":"exercise-0679-standing-calf-raise-machine","name":"Standing Calf Raise (Machine)","sets":3,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0068-bird-dog-pas-koji-trazi-prticicu","name":"Bird Dog (Pas koji traži prtičicu)","sets":2,"reps":"8","rest_seconds":45,"rpe":6,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."}]}]},"de":{"name":"Oberkörper / Unterkörper · 4 Tage","description":"Ausgewogener Ablauf: Oberkörper, Unterkörper, Pause, Oberkörper, Unterkörper. Ein wiederholbarer nächster Schritt nach Ganzkörpertraining.\n\nDie angegebene Woche wiederholen. Am unteren Ende des Wiederholungsbereichs mit 3–4 Wiederholungen Reserve (RPE 6–7) beginnen. Bei guter Kontrolle eine Wiederholung pro Satz ergänzen; erreichen alle Sätze die Obergrenze, das kleinste verfügbare Gewicht hinzufügen und unten beginnen. Gewicht und Satzzahl nicht gleichzeitig erhöhen. Bei schlechterer Erholung oder Technik die Vorwoche wiederholen oder einen Satz streichen.\n\nEin eigenes allgemeines Beispiel für Erwachsene ohne individuelle Untersuchung. Übungen und Geräte zuerst prüfen. Mit leichten Übungssätzen beginnen; bei Schmerzen oder Unwohlsein stoppen. Zwischen schweren Einheiten Erholung einplanen. Bei gesundheitlichen Einschränkungen, Schwangerschaft oder Verletzung anpassen oder fachlichen Rat einholen.","weeks":8,"days":[{"title":"A · Oberkörper","exercises":[{"catalogue_id":"exercise-0060-bench-press-potisak-s-ravne-klupe","name":"Bench Press (Potisak s ravne klupe)","sets":3,"reps":"6–10","rest_seconds":150,"rpe":7,"section":"main","notes":"Bei Bedarf ein Rack mit passend eingestellten Sicherungen oder eine erfahrene Hilfsperson nutzen. Vor den Arbeitssätzen mit leichteren Übungssätzen aufwärmen."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0227-dumbbell-lateral-raise","name":"Dumbbell Lateral Raise","sets":2,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0554-rope-triceps-pushdown","name":"Rope Triceps Pushdown","sets":2,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."}]},{"title":"A · Unterkörper","exercises":[{"catalogue_id":"exercise-0035-back-squat-cucanj-sa-sipkom","name":"Back Squat (Čučanj sa šipkom)","sets":3,"reps":"6–10","rest_seconds":180,"rpe":7,"section":"main","notes":"Bei Bedarf ein Rack mit passend eingestellten Sicherungen oder eine erfahrene Hilfsperson nutzen. Vor den Arbeitssätzen mit leichteren Übungssätzen aufwärmen."},{"catalogue_id":"exercise-0549-romanian-deadlift","name":"Romanian Deadlift","sets":3,"reps":"8–10","rest_seconds":150,"rpe":7,"section":"main","notes":"Bei Bedarf ein Rack mit passend eingestellten Sicherungen oder eine erfahrene Hilfsperson nutzen. Vor den Arbeitssätzen mit leichteren Übungssätzen aufwärmen."},{"catalogue_id":"exercise-0392-leg-extension-machine","name":"Leg Extension (Machine)","sets":2,"reps":"10–15","rest_seconds":75,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0575-seated-calf-raise","name":"Seated Calf Raise","sets":3,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"8–10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."}]},{"title":"B · Oberkörper","exercises":[{"catalogue_id":"exercise-0330-incline-bench-press-kosi-potisak-gornji-dio-prsa","name":"Incline Bench Press (Kosi potisak — gornji dio prsa)","sets":3,"reps":"8–12","rest_seconds":120,"rpe":7,"section":"main","notes":"Bei Bedarf ein Rack mit passend eingestellten Sicherungen oder eine erfahrene Hilfsperson nutzen. Vor den Arbeitssätzen mit leichteren Übungssätzen aufwärmen."},{"catalogue_id":"exercise-0152-chest-supported-row-veslanje-s-osloncem-na-prsa","name":"Chest Supported Row (Veslanje s osloncem na prsa)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0227-dumbbell-lateral-raise","name":"Dumbbell Lateral Raise","sets":2,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0218-dumbbell-biceps-curl","nam