('kinra-strength-conditioning','training',1,'{"en":{"name":"Strength + movement · 3 days","description":"Two strength sessions and a counted movement circuit. The circuit is a conditioning example, not a complete weekly aerobic prescription.\n\nRepeat the listed week. Begin at the low end of each rep range with 3–4 reps in reserve (RPE 6–7). Add one rep per set when controlled; after every set reaches the top, increase the smallest available load and return to the low end. Do not increase load and sets together. If recovery or form worsens, repeat the previous week or remove one set.\n\nAn original general adult example, not an individually assessed prescription. Review exercises and equipment first. Start with easy practice sets; stop for pain or feeling unwell. Schedule rest between hard sessions. Adjust or seek qualified guidance when health, pregnancy or injury affects exercise.","weeks":6,"days":[{"title":"A · Full body","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0628-single-arm-dumbbell-row-jednoruko-veslanje-bucicom","name":"Single-Arm Dumbbell Row (Jednoruko veslanje bučicom)","sets":3,"reps":"10","rest_seconds":90,"rpe":7,"section":"main","notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."},{"catalogue_id":"exercise-0364-knee-push-up-skleka-s-koljenima","name":"Knee Push-Up (Skleka s koljenima)","sets":3,"reps":"8–12","rest_seconds":75,"rpe":7,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0224-dumbbell-glute-bridge","name":"Dumbbell Glute Bridge","sets":2,"reps":"12–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."}]},{"title":"B · Counted movement circuit","exercises":[{"catalogue_id":"exercise-0688-step-touch-march-oblikovanje-korak-dodir-za-oblikovanje","name":"Step Touch / March — Oblikovanje (Korak-dodir za oblikovanje)","sets":3,"reps":"30","rest_seconds":45,"rpe":5,"section":"main","weight":0,"notes":"Count complete movement cycles, not seconds. Use a conversational effort and take longer rest if needed."},{"catalogue_id":"exercise-0071-bodyweight-squat-cucanj-s-tjelesnom-tezinom","name":"Bodyweight Squat (Čučanj s tjelesnom težinom)","sets":3,"reps":"12","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0354-jumping-jacks-raznoska","name":"Jumping Jacks (Raznoška)","sets":3,"reps":"15","rest_seconds":60,"rpe":5,"section":"main","weight":0,"notes":"Count complete movement cycles, not seconds. Use a conversational effort and take longer rest if needed."},{"catalogue_id":"exercise-0068-bird-dog-pas-koji-trazi-prticicu","name":"Bird Dog (Pas koji traži prtičicu)","sets":3,"reps":"6","rest_seconds":45,"rpe":5,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."}]},{"title":"C · Full body","exercises":[{"catalogue_id":"exercise-0228-dumbbell-lunges-iskoraci-s-bucicama","name":"Dumbbell Lunges (Iskoraci s bučicama)","sets":2,"reps":"8–10","rest_seconds":90,"rpe":7,"section":"main","notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0628-single-arm-dumbbell-row-jednoruko-veslanje-bucicom","name":"Single-Arm Dumbbell Row (Jednoruko veslanje bučicom)","sets":3,"reps":"10–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"8","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."}]}]},"bs":{"name":"Snaga i kretanje · 3 dana","description":"Dva treninga snage i kružni trening uz brojanje pokreta. Krug je primjer kondicijskog rada, a ne potpuni sedmični aerobni plan.\n\nPonavljajte prikazanu sedmicu. Počnite donjim brojem ponavljanja uz 3–4 ponavljanja u rezervi (RPE 6–7). Dodajte po jedno kontrolisano ponavljanje u seriji; kada sve serije dostignu gornju granicu, dodajte najmanje dostupno opterećenje i vratite se donjoj. Ne povećavajte istovremeno opterećenje i broj serija. Ako oporavak ili tehnika oslabe, ponovite prethodnu sedmicu ili uklonite jednu seriju.\n\nOriginalni opći primjer za odrasle, bez individualne procjene. Prvo pregledajte vježbe i opremu. Počnite laganim probnim serijama; stanite kod bola ili lošeg osjećaja. Ostavite odmor između težih treninga. Prilagodite plan ili zatražite stručni savjet ako zdravlje, trudnoća ili povreda utiču na vježbanje.","weeks":6,"days":[{"title":"A · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0628-single-arm-dumbbell-row-jednoruko-veslanje-bucicom","name":"Single-Arm Dumbbell Row (Jednoruko veslanje bučicom)","sets":3,"reps":"10","rest_seconds":90,"rpe":7,"section":"main","notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."},{"catalogue_id":"exercise-0364-knee-push-up-skleka-s-koljenima","name":"Knee Push-Up (Skleka s koljenima)","sets":3,"reps":"8–12","rest_seconds":75,"rpe":7,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0224-dumbbell-glute-bridge","name":"Dumbbell Glute Bridge","sets":2,"reps":"12–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."}]},{"title":"B · Krug s brojanjem pokreta","exercises":[{"catalogue_id":"exercise-0688-step-touch-march-oblikovanje-korak-dodir-za-oblikovanje","name":"Step Touch / March — Oblikovanje (Korak-dodir za oblikovanje)","sets":3,"reps":"30","rest_seconds":45,"rpe":5,"section":"main","weight":0,"notes":"Brojite pune cikluse pokreta, ne sekunde. Radite tempom pri kojem možete razgovarati i po potrebi odmorite duže."},{"catalogue_id":"exercise-0071-bodyweight-squat-cucanj-s-tjelesnom-tezinom","name":"Bodyweight Squat (Čučanj s tjelesnom težinom)","sets":3,"reps":"12","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0354-jumping-jacks-raznoska","name":"Jumping Jacks (Raznoška)","sets":3,"reps":"15","rest_seconds":60,"rpe":5,"section":"main","weight":0,"notes":"Brojite pune cikluse pokreta, ne sekunde. Radite tempom pri kojem možete razgovarati i po potrebi odmorite duže."},{"catalogue_id":"exercise-0068-bird-dog-pas-koji-trazi-prticicu","name":"Bird Dog (Pas koji traži prtičicu)","sets":3,"reps":"6","rest_seconds":45,"rpe":5,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."}]},{"title":"C · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0228-dumbbell-lunges-iskoraci-s-bucicama","name":"Dumbbell Lunges (Iskoraci s bučicama)","sets":2,"reps":"8–10","rest_seconds":90,"rpe":7,"section":"main","notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0628-single-arm-dumbbell-row-jednoruko-veslanje-bucicom","name":"Single-Arm Dumbbell Row (Jednoruko veslanje bučicom)","sets":3,"reps":"10–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"8","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."}]}]},"de":{"name":"Kraft + Bewegung · 3 Tage","description":"Zwei Krafteinheiten und ein gezählter Bewegungszirkel. Der Zirkel ist ein Konditionsbeispiel, kein vollständiger Wochenplan für Ausdauer.\n\nDie angegebene Woche wiederholen. Am unteren Ende des Wiederholungsbereichs mit 3–4 Wiederholungen Reserve (RPE 6–7) beginnen. Bei guter Kontrolle eine Wiederholung pro Satz ergänzen; erreichen alle Sätze die Obergrenze, das kleinste verfügbare Gewicht hinzufügen und unten beginnen. Gewicht und Satzzahl nicht gleichzeitig erhöhen. Bei schlechterer Erholung oder Technik die Vorwoche wiederholen oder einen Satz streichen.\n\nEin eigenes allgemeines Beispiel für Erwachsene ohne individuelle Untersuchung. Übungen und Geräte zuerst prüfen. Mit leichten Übungssätzen beginnen; bei Schmerzen oder Unwohlsein stoppen. Zwischen schweren Einheiten Erholung einplanen. Bei gesundheitlichen Einschränkungen, Schwangerschaft oder Verletzung anpassen oder fachlichen Rat einholen.","weeks":6,"days":[{"title":"A · Ganzkörper","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0628-single-arm-dumbbell-row-jednoruko-veslanje-bucicom","name":"Single-Arm Dumbbell Row (Jednoruko veslanje bučicom)","sets":3,"reps":"10","rest_seconds":90,"rpe":7,"section":"main","notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."},{"catalogue_id":"exercise-0364-knee-push-up-skleka-s-koljenima","name":"Knee Push-Up (Skleka s koljenima)","sets":3,"reps":"8–12","rest_seconds":75,"rpe":7,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0224-dumbbell-glute-bridge","name":"Dumbbell Glute Bridge","sets":2,"reps":"12–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."}]},{"title":"B · Gezählter Bewegungszirkel","exercises":[{"catalogue_id":"exercise-0688-step-touch-march-oblikovanje-korak-dodir-za-oblikovanje","name":"Step Touch / March — Oblikovanje (Korak-dodir za oblikovanje)","sets":3,"reps":"30","rest_seconds":45,"rpe":5,"section":"main","weight":0,"notes":"Vollständige Bewegungszyklen zählen, keine Sekunden. Bei Gesprächstempo arbeiten und bei Bedarf länger pausieren."},{"catalogue_id":"exercise-0071-bodyweight-squat-cucanj-s-tjelesnom-tezinom","name":"Bodyweight Squat (Čučanj s tjelesnom težinom)","sets":3,"reps":"12","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0354-jumping-jacks-raznoska","name":"Jumping Jacks (Raznoška)","sets":3,"reps":"15","rest_seconds":60,"rpe":5,"section":"main","weight":0,"notes":"Vollständige Bewegungszyklen zählen, keine Sekunden. Bei Gesprächstempo arbeiten und bei Bedarf länger pausieren."},{"catalogue_id":"exercise-0068-bird-dog-pas-koji-trazi-prticicu","name":"Bird Dog (Pas koji traži prtičicu)","sets":3,"reps":"6","rest_seconds":45,"rpe":5,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."}]},{"title":"C · Ganzkörper","exercises":[{"catalogue_id":"exercise-0228-dumbbell-lunges-iskoraci-s-bucicama","name":"Dumbbell Lunges (Iskoraci s bučicama)","sets":2,"reps":"8–10","rest_seconds":90,"rpe":7,"section":"main","notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0628-single-arm-dumbbell-row-jednoruko-veslanje-bucicom","name":"Single-Arm Dumbbell Row (Jednoruko veslanje bučicom)","sets":3,"reps":"10–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"8","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."}]}]}}'::jsonb),
('kinra-kettlebell-basics','training',1,'{"en":{"name":"Kettlebell basics · 2 days","description":"Controlled strength with a single kettlebell and bodyweight. No ballistic swings or snatches are required.\n\nRepeat the listed week. Begin at the low end of each rep range with 3–4 reps in reserve (RPE 6–7). Add one rep per set when controlled; after every set reaches the top, increase the smallest available load and return to the low end. Do not increase load and sets together. If recovery or form worsens, repeat the previous week or remove one set.\n\nAn original general adult example, not an individually assessed prescription. Review exercises and equipment first. Start with easy practice sets; stop for pain or feeling unwell. Schedule rest between hard sessions. Adjust or seek qualified guidance when health, pregnancy or injury affects exercise. This minimal-equipment example lacks loaded pulling. Pair with a reviewed row variation when suitable equipment is available.","weeks":6,"days":[{"title":"A · Full body","exercises":[{"catalogue_id":"exercise-0356-kettlebell-goblet-squat","name":"Kettlebell Goblet Squat","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0364-knee-push-up-skleka-s-koljenima","name":"Knee Push-Up (Skleka s koljenima)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0282-glute-bridge-most-straznjice","name":"Glute Bridge (Most stražnjice)","sets":3,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0068-bird-dog-pas-koji-trazi-prticicu","name":"Bird Dog (Pas koji traži prtičicu)","sets":2,"reps":"8","rest_seconds":45,"rpe":6,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."}]},{"title":"B · Full body","exercises":[{"catalogue_id":"exercise-0356-kettlebell-goblet-squat","name":"Kettlebell Goblet Squat","sets":3,"reps":"10–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0542-reverse-lunge-iskorak-unazad","name":"Reverse Lunge (Iskorak unazad)","sets":3,"reps":"8","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."},{"catalogue_id":"exercise-0507-push-up-skleka","name":"Push-Up (Skleka)","sets":2,"reps":"6–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"8","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."}]}]},"bs":{"name":"Osnove s girjom · 2 dana","description":"Kontrolisana snaga s jednom girjom i vlastitom težinom. Nisu potrebni zamasi ni trzaji.\n\nPonavljajte prikazanu sedmicu. Počnite donjim brojem ponavljanja uz 3–4 ponavljanja u rezervi (RPE 6–7). Dodajte po jedno kontrolisano ponavljanje u seriji; kada sve serije dostignu gornju granicu, dodajte najmanje dostupno opterećenje i vratite se donjoj. Ne povećavajte istovremeno opterećenje i broj serija. Ako oporavak ili tehnika oslabe, ponovite prethodnu sedmicu ili uklonite jednu seriju.\n\nOriginalni opći primjer za odrasle, bez individualne procjene. Prvo pregledajte vježbe i opremu. Počnite laganim probnim serijama; stanite kod bola ili lošeg osjećaja. Ostavite odmor između težih treninga. Prilagodite plan ili zatražite stručni savjet ako zdravlje, trudnoća ili povreda utiču na vježbanje. Ovaj primjer s malo opreme nema povlačenje s opterećenjem. Dopunite pregledanom varijantom veslanja kada imate odgovarajuću opremu.","weeks":6,"days":[{"title":"A · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0356-kettlebell-goblet-squat","name":"Kettlebell Goblet Squat","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0364-knee-push-up-skleka-s-koljenima","name":"Knee Push-Up (Skleka s koljenima)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0282-glute-bridge-most-straznjice","name":"Glute Bridge (Most stražnjice)","sets":3,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0068-bird-dog-pas-koji-trazi-prticicu","name":"Bird Dog (Pas koji traži prtičicu)","sets":2,"reps":"8","rest_seconds":45,"rpe":6,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."}]},{"title":"B · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0356-kettlebell-goblet-squat","name":"Kettlebell Goblet Squat","sets":3,"reps":"10–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0542-reverse-lunge-iskorak-unazad","name":"Reverse Lunge (Iskorak unazad)","sets":3,"reps":"8","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."},{"catalogue_id":"exercise-0507-push-up-skleka","name":"Push-Up (Skleka)","sets":2,"reps":"6–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"8","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."}]}]},"de":{"name":"Kettlebell-Grundlagen · 2 Tage","description":"Kontrollierte Kraft mit einer Kettlebell und Körpergewicht. Keine ballistischen Swings oder Snatches erforderlich.\n\nDie angegebene Woche wiederholen. Am unteren Ende des Wiederholungsbereichs mit 3–4 Wiederholungen Reserve (RPE 6–7) beginnen. Bei guter Kontrolle eine Wiederholung pro Satz ergänzen; erreichen alle Sätze die Obergrenze, das kleinste verfügbare Gewicht hinzufügen und unten beginnen. Gewicht und Satzzahl nicht gleichzeitig erhöhen. Bei schlechterer Erholung oder Technik die Vorwoche wiederholen oder einen Satz streichen.\n\nEin eigenes allgemeines Beispiel für Erwachsene ohne individuelle Untersuchung. Übungen und Geräte zuerst prüfen. Mit leichten Übungssätzen beginnen; bei Schmerzen oder Unwohlsein stoppen. Zwischen schweren Einheiten Erholung einplanen. Bei gesundheitlichen Einschränkungen, Schwangerschaft oder Verletzung anpassen oder fachlichen Rat einholen. Diesem Beispiel mit wenig Geräten fehlt belastetes Ziehen. Bei geeigneter Ausrüstung eine geprüfte Ruderübung ergänzen.","weeks":6,"days":[{"title":"A · Ganzkörper","exercises":[{"catalogue_id":"exercise-0356-kettlebell-goblet-squat","name":"Kettlebell Goblet Squat","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0364-knee-push-up-skleka-s-koljenima","name":"Knee Push-Up (Skleka s koljenima)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0282-glute-bridge-most-straznjice","name":"Glute Bridge (Most stražnjice)","sets":3,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0068-bird-dog-pas-koji-trazi-prticicu","name":"Bird Dog (Pas koji traži prtičicu)","sets":2,"reps":"8","rest_seconds":45,"rpe":6,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."}]},{"title":"B · Ganzkörper","exercises":[{"catalogue_id":"exercise-0356-kettlebell-goblet-squat","name":"Kettlebell Goblet Squat","sets":3,"reps":"10–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0542-reverse-lunge-iskorak-unazad","name":"Reverse Lunge (Iskorak unazad)","sets":3,"reps":"8","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."},{"catalogue_id":"exercise-0507-push-up-skleka","name":"Push-Up (Skleka)","sets":2,"reps":"6–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"8","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."}]}]}}'::jsonb),
('kinra-machine-circuit','training',1,'{"en":{"name":"Machine circuit · 2 days","description":"A machine-based full-body routine with simple setup. Complete all sets on each station before moving on.\n\nRepeat the listed week. Begin at the low end of each rep range with 3–4 reps in reserve (RPE 6–7). Add one rep per set when controlled; after every set reaches the top, increase the smallest available load and return to the low end. Do not increase load and sets together. If recovery or form worsens, repeat the previous week or remove one set.\n\nAn original general adult example, not an individually assessed prescription. Review exercises and equipment first. Start with easy practice sets; stop for pain or feeling unwell. Schedule rest between hard sessions. Adjust or seek qualified guidance when health, pregnancy or injury affects exercise.","weeks":6,"days":[{"title":"A · Full body","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0266-flat-machine-chest-press-wide-grip","name":"Flat Machine Chest Press (Wide Grip)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0413-machine-neutral-grip-lat-pulldown","name":"Machine Neutral Grip Lat Pulldown","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0582-seated-leg-curl-machine","name":"Seated Leg Curl (Machine)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0679-standing-calf-raise-machine","name":"Standing Calf Raise (Machine)","sets":2,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."}]},{"title":"B · Full body","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0266-flat-machine-chest-press-wide-grip","name":"Flat Machine Chest Press (Wide Grip)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0392-leg-extension-machine","name":"Leg Extension (Machine)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0417-machine-triceps-extension","name":"Machine Triceps Extension","sets":2,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."}]}]},"bs":{"name":"Krug na spravama · 2 dana","description":"Trening cijelog tijela na spravama s jednostavnom pripremom. Završite sve serije na spravi prije prelaska dalje.\n\nPonavljajte prikazanu sedmicu. Počnite donjim brojem ponavljanja uz 3–4 ponavljanja u rezervi (RPE 6–7). Dodajte po jedno kontrolisano ponavljanje u seriji; kada sve serije dostignu gornju granicu, dodajte najmanje dostupno opterećenje i vratite se donjoj. Ne povećavajte istovremeno opterećenje i broj serija. Ako oporavak ili tehnika oslabe, ponovite prethodnu sedmicu ili uklonite jednu seriju.\n\nOriginalni opći primjer za odrasle, bez individualne procjene. Prvo pregledajte vježbe i opremu. Počnite laganim probnim serijama; stanite kod bola ili lošeg osjećaja. Ostavite odmor između težih treninga. Prilagodite plan ili zatražite stručni savjet ako zdravlje, trudnoća ili povreda utiču na vježbanje.","weeks":6,"days":[{"title":"A · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0266-flat-machine-chest-press-wide-grip","name":"Flat Machine Chest Press (Wide Grip)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0413-machine-neutral-grip-lat-pulldown","name":"Machine Neutral Grip Lat Pulldown","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0582-seated-leg-curl-machine","name":"Seated Leg Curl (Machine)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0679-standing-calf-raise-machine","name":"Standing Calf Raise (Machine)","sets":2,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."}]},{"title":"B · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0266-flat-machine-chest-press-wide-grip","name":"Flat Machine Chest Press (Wide Grip)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0392-leg-extension-machine","name":"Leg Extension (Machine)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0417-machine-triceps-extension","name":"Machine Triceps Extension","sets":2,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."}]}]},"de":{"name":"Gerätezirkel · 2 Tage","description":"Eine Ganzkörperroutine an Geräten mit einfacher Vorbereitung. Alle Sätze an einer Station abschließen, dann wechseln.\n\nDie angegebene Woche wiederholen. Am unteren Ende des Wiederholungsbereichs mit 3–4 Wiederholungen Reserve (RPE 6–7) beginnen. Bei guter Kontrolle eine Wiederholung pro Satz ergänzen; erreichen alle Sätze die Obergrenze, das kleinste verfügbare Gewicht hinzufügen und unten beginnen. Gewicht und Satzzahl nicht gleichzeitig erhöhen. Bei schlechterer Erholung oder Technik die Vorwoche wiederholen oder einen Satz streichen.\n\nEin eigenes allgemeines Beispiel für Erwachsene ohne individuelle Untersuchung. Übungen und Geräte zuerst prüfen. Mit leichten Übungssätzen beginnen; bei Schmerzen oder Unwohlsein stoppen. Zwischen schweren Einheiten Erholung einplanen. Bei gesundheitlichen Einschränkungen, Schwangerschaft oder Verletzung anpassen oder fachlichen Rat einholen.","weeks":6,"days":[{"title":"A · Ganzkörper","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0266-flat-machine-chest-press-wide-grip","name":"Flat Machine Chest Press (Wide Grip)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0413-machine-neutral-grip-lat-pulldown","name":"Machine Neutral Grip Lat Pulldown","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0582-seated-leg-curl-machine","name":"Seated Leg Curl (Machine)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0679-standing-calf-raise-machine","name":"Standing Calf Raise (Machine)","sets":2,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."}]},{"title":"B · Ganzkörper","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0266-flat-machine-chest-press-wide-grip","name":"Flat Machine Chest Press (Wide Grip)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0392-leg-extension-machine","name":"Leg Extension (Machine)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0417-machine-triceps-extension","name":"Machine Triceps Extension","sets":2,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."}]}]}}'::jsonb),
('kinra-short-sessions','training',1,'{"en":{"name":"Short gym sessions · 2 days","description":"Four movements per session for busy weeks. A small repeatable routine with squat, hinge, push and pull patterns.\n\nRepeat the listed week. Begin at the low end of each rep range with 3–4 reps in reserve (RPE 6–7). Add one rep per set when controlled; after every set reaches the top, increase the smallest available load and return to the low end. Do not increase load and sets together. If recovery or form worsens, repeat the previous week or remove one set.\n\nAn original general adult example, not an individually assessed prescription. Review exercises and equipment first. Start with easy practice sets; stop for pain or feeling unwell. Schedule rest between hard sessions. Adjust or seek qualified guidance when health, pregnancy or injury affects exercise.","weeks":4,"days":[{"title":"A · Full body","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0266-flat-machine-chest-press-wide-grip","name":"Flat Machine Chest Press (Wide Grip)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"8","rest_seconds":45,"rpe":6,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."}]},{"title":"B · Full body","exercises":[{"catalogue_id":"exercise-0549-romanian-deadlift","name":"Romanian Deadlift","sets":2,"reps":"8–12","rest_seconds":120,"rpe":7,"section":"main","notes":"Use a rack with correctly set safeties or a competent spotter where needed. Warm up with lighter practice sets before the working sets."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0542-reverse-lunge-iskorak-unazad","name":"Reverse Lunge (Iskorak unazad)","sets":2,"reps":"8","rest_seconds":75,"rpe":7,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."}]}]},"bs":{"name":"Kratki treninzi u teretani · 2 dana","description":"Četiri pokreta po treningu za zauzete sedmice. Kratak ponovljiv plan s čučnjem, pregibom u kuku, potiskom i povlačenjem.\n\nPonavljajte prikazanu sedmicu. Počnite donjim brojem ponavljanja uz 3–4 ponavljanja u rezervi (RPE 6–7). Dodajte po jedno kontrolisano ponavljanje u seriji; kada sve serije dostignu gornju granicu, dodajte najmanje dostupno opterećenje i vratite se donjoj. Ne povećavajte istovremeno opterećenje i broj serija. Ako oporavak ili tehnika oslabe, ponovite prethodnu sedmicu ili uklonite jednu seriju.\n\nOriginalni opći primjer za odrasle, bez individualne procjene. Prvo pregledajte vježbe i opremu. Počnite laganim probnim serijama; stanite kod bola ili lošeg osjećaja. Ostavite odmor između težih treninga. Prilagodite plan ili zatražite stručni savjet ako zdravlje, trudnoća ili povreda utiču na vježbanje.","weeks":4,"days":[{"title":"A · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0266-flat-machine-chest-press-wide-grip","name":"Flat Machine Chest Press (Wide Grip)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"8","rest_seconds":45,"rpe":6,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."}]},{"title":"B · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0549-romanian-deadlift","name":"Romanian Deadlift","sets":2,"reps":"8–12","rest_seconds":120,"rpe":7,"section":"main","notes":"Po potrebi koristite stalak s pravilno postavljenim osiguračima ili sposobnog pomagača. Prije radnih serija uradite lakše probne serije."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0542-reverse-lunge-iskorak-unazad","name":"Reverse Lunge (Iskorak unazad)","sets":2,"reps":"8","rest_seconds":75,"rpe":7,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."}]}]},"de":{"name":"Kurze Studioeinheiten · 2 Tage","description":"Vier Bewegungen je Einheit für volle Wochen. Eine kleine wiederholbare Routine mit Kniebeuge, Hüftbeuge, Drücken und Ziehen.\n\nDie angegebene Woche wiederholen. Am unteren Ende des Wiederholungsbereichs mit 3–4 Wiederholungen Reserve (RPE 6–7) beginnen. Bei guter Kontrolle eine Wiederholung pro Satz ergänzen; erreichen alle Sätze die Obergrenze, das kleinste verfügbare Gewicht hinzufügen und unten beginnen. Gewicht und Satzzahl nicht gleichzeitig erhöhen. Bei schlechterer Erholung oder Technik die Vorwoche wiederholen oder einen Satz streichen.\n\nEin eigenes allgemeines Beispiel für Erwachsene ohne individuelle Untersuchung. Übungen und Geräte zuerst prüfen. Mit leichten Übungssätzen beginnen; bei Schmerzen oder Unwohlsein stoppen. Zwischen schweren Einheiten Erholung einplanen. Bei gesundheitlichen Einschränkungen, Schwangerschaft oder Verletzung anpassen oder fachlichen Rat einholen.","weeks":4,"days":[{"title":"A · Ganzkörper","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0266-flat-machine-chest-press-wide-grip","name":"Flat Machine Chest Press (Wide Grip)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"8","rest_seconds":45,"rpe":6,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."}]},{"title":"B · Ganzkörper","exercises":[{"catalogue_id":"exercise-0549-romanian-deadlift","name":"Romanian Deadlift","sets":2,"reps":"8–12","rest_seconds":120,"rpe":7,"section":"main","notes":"Bei Bedarf ein Rack mit passend eingestellten Sicherungen oder eine erfahrene Hilfsperson nutzen. Vor den Arbeitssätzen mit leichteren Übungssätzen aufwärmen."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0542-reverse-lunge-iskorak-unazad","name":"Reverse Lunge (Iskorak unazad)","sets":2,"reps":"8","rest_seconds":75,"rpe":7,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."}]}]}}'::jsonb),
('kinra-cable-dumbbell','training',1,'{"en":{"name":"Cable + dumbbell · 3 days","description":"Full-body training without barbell racks. Rotate cable pulling, dumbbell leg work and machine pressing.\n\nRepeat the listed week. Begin at the low end of each rep range with 3–4 reps in reserve (RPE 6–7). Add one rep per set when controlled; after every set reaches the top, increase the smallest available load and return to the low end. Do not increase load and sets together. If recovery or form worsens, repeat the previous week or remove one set.\n\nAn original general adult example, not an individually assessed prescription. Review exercises and equipment first. Start with easy practice sets; stop for pain or feeling unwell. Schedule rest between hard sessions. Adjust or seek qualified guidance when health, pregnancy or injury affects exercise.","weeks":6,"days":[{"title":"A · Full body","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0266-flat-machine-chest-press-wide-grip","name":"Flat Machine Chest Press (Wide Grip)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0582-seated-leg-curl-machine","name":"Seated Leg Curl (Machine)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0227-dumbbell-lateral-raise","name":"Dumbbell Lateral Raise","sets":2,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."}]},{"title":"B · Full body","exercises":[{"catalogue_id":"exercise-0228-dumbbell-lunges-iskoraci-s-bucicama","name":"Dumbbell Lunges (Iskoraci s bučicama)","sets":3,"reps":"8–10","rest_seconds":90,"rpe":7,"section":"main","notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0224-dumbbell-glute-bridge","name":"Dumbbell Glute Bridge","sets":3,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0218-dumbbell-biceps-curl","name":"Dumbbell Biceps Curl","sets":2,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."}]},{"title":"C · Full body","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0628-single-arm-dumbbell-row-jednoruko-veslanje-bucicom","name":"Single-Arm Dumbbell Row (Jednoruko veslanje bučicom)","sets":3,"reps":"10–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."},{"catalogue_id":"exercise-0676-standing-cable-chest-press","name":"Standing Cable Chest Press","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0582-seated-leg-curl-machine","name":"Seated Leg Curl (Machine)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0554-rope-triceps-pushdown","name":"Rope Triceps Pushdown","sets":2,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."}]}]},"bs":{"name":"Sajle i bučice · 3 dana","description":"Trening cijelog tijela bez stalka za šipku. Smjenjujte povlačenja sajlom, rad nogu s bučicama i potiske na spravama.\n\nPonavljajte prikazanu sedmicu. Počnite donjim brojem ponavljanja uz 3–4 ponavljanja u rezervi (RPE 6–7). Dodajte po jedno kontrolisano ponavljanje u seriji; kada sve serije dostignu gornju granicu, dodajte najmanje dostupno opterećenje i vratite se donjoj. Ne povećavajte istovremeno opterećenje i broj serija. Ako oporavak ili tehnika oslabe, ponovite prethodnu sedmicu ili uklonite jednu seriju.\n\nOriginalni opći primjer za odrasle, bez individualne procjene. Prvo pregledajte vježbe i opremu. Počnite laganim probnim serijama; stanite kod bola ili lošeg osjećaja. Ostavite odmor između težih treninga. Prilagodite plan ili zatražite stručni savjet ako zdravlje, trudnoća ili povreda utiču na vježbanje.","weeks":6,"days":[{"title":"A · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0266-flat-machine-chest-press-wide-grip","name":"Flat Machine Chest Press (Wide Grip)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0582-seated-leg-curl-machine","name":"Seated Leg Curl (Machine)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0227-dumbbell-lateral-raise","name":"Dumbbell Lateral Raise","sets":2,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."}]},{"title":"B · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0228-dumbbell-lunges-iskoraci-s-bucicama","name":"Dumbbell Lunges (Iskoraci s bučicama)","sets":3,"reps":"8–10","rest_seconds":90,"rpe":7,"section":"main","notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0224-dumbbell-glute-bridge","name":"Dumbbell Glute Bridge","sets":3,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0218-dumbbell-biceps-curl","name":"Dumbbell Biceps Curl","sets":2,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."}]},{"title":"C · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0628-single-arm-dumbbell-row-jednoruko-veslanje-bucicom","name":"Single-Arm Dumbbell Row (Jednoruko veslanje bučicom)","sets":3,"reps":"10–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."},{"catalogue_id":"exercise-0676-standing-cable-chest-press","name":"Standing Cable Chest Press","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0582-seated-leg-curl-machine","name":"Seated Leg Curl (Machine)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0554-rope-triceps-pushdown","name":"Rope Triceps Pushdown","sets":2,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."}]}]},"de":{"name":"Kabel + Kurzhantel · 3 Tage","description":"Ganzkörpertraining ohne Langhantelrack. Kabelziehen, Beinarbeit mit Kurzhanteln und Gerätedrücken im Wechsel.\n\nDie angegebene Woche wiederholen. Am unteren Ende des Wiederholungsbereichs mit 3–4 Wiederholungen Reserve (RPE 6–7) beginnen. Bei guter Kontrolle eine Wiederholung pro Satz ergänzen; erreichen alle Sätze die Obergrenze, das kleinste verfügbare Gewicht hinzufügen und unten beginnen. Gewicht und Satzzahl nicht gleichzeitig erhöhen. Bei schlechterer Erholung oder Technik die Vorwoche wiederholen oder einen Satz streichen.\n\nEin eigenes allgemeines Beispiel für Erwachsene ohne individuelle Untersuchung. Übungen und Geräte zuerst prüfen. Mit leichten Übungssätzen beginnen; bei Schmerzen oder Unwohlsein stoppen. Zwischen schweren Einheiten Erholung einplanen. Bei gesundheitlichen Einschränkungen, Schwangerschaft oder Verletzung anpassen oder fachlichen Rat einholen.","weeks":6,"days":[{"title":"A · Ganzkörper","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0266-flat-machine-chest-press-wide-grip","name":"Flat Machine Chest Press (Wide Grip)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0582-seated-leg-curl-machine","name":"Seated Leg Curl (Machine)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0227-dumbbell-lateral-raise","name":"Dumbbell Lateral Raise","sets":2,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."}]},{"title":"B · Ganzkörper","exercises":[{"catalogue_id":"exercise-0228-dumbbell-lunges-iskoraci-s-bucicama","name":"Dumbbell Lunges (Iskoraci s bučicama)","sets":3,"reps":"8–10","rest_seconds":90,"rpe":7,"section":"main","notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0224-dumbbell-glute-bridge","name":"Dumbbell Glute Bridge","sets":3,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0218-dumbbell-biceps-curl","name":"Dumbbell Biceps Curl","sets":2,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."}]},{"title":"C · Ganzkörper","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0628-single-arm-dumbbell-row-jednoruko-veslanje-bucicom","name":"Single-Arm Dumbbell Row (Jednoruko veslanje bučicom)","sets":3,"reps":"10–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."},{"catalogue_id":"exercise-0676-standing-cable-chest-press","name":"Standing Cable Chest Press","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0582-seated-leg-curl-machine","name":"Seated Leg Curl (Machine)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0554-rope-triceps-pushdown","name":"Rope Triceps Pushdown","sets":2,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."}]}]}}'::jsonb),
('kinra-lower-focus','training',1,'{"en":{"name":"Lower-body focus · 2 days","description":"Two leg-focused sessions for an existing balanced schedule. Add your reviewed upper-body sessions; this is not a full-body week.\n\nRepeat the listed week. Begin at the low end of each rep range with 3–4 reps in reserve (RPE 6–7). Add one rep per set when controlled; after every set reaches the top, increase the smallest available load and return to the low end. Do not increase load and sets together. If recovery or form worsens, repeat the previous week or remove one set.\n\nAn original general adult example, not an individually assessed prescription. Review exercises and equipment first. Start with easy practice sets; stop for pain or feeling unwell. Schedule rest between hard sessions. Adjust or seek qualified guidance when health, pregnancy or injury affects exercise.","weeks":6,"days":[{"title":"A · Lower","exercises":[{"catalogue_id":"exercise-0035-back-squat-cucanj-sa-sipkom","name":"Back Squat (Čučanj sa šipkom)","sets":3,"reps":"6–10","rest_seconds":180,"rpe":7,"section":"main","notes":"Use a rack with correctly set safeties or a competent spotter where needed. Warm up with lighter practice sets before the working sets."},{"catalogue_id":"exercise-0549-romanian-deadlift","name":"Romanian Deadlift","sets":3,"reps":"8–10","rest_seconds":150,"rpe":7,"section":"main","notes":"Use a rack with correctly set safeties or a competent spotter where needed. Warm up with lighter practice sets before the working sets."},{"catalogue_id":"exercise-0392-leg-extension-machine","name":"Leg Extension (Machine)","sets":2,"reps":"10–15","rest_seconds":75,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0575-seated-calf-raise","name":"Seated Calf Raise","sets":3,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"8–10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."}]},{"title":"B · Lower","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":3,"reps":"10–12","rest_seconds":120,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0582-seated-leg-curl-machine","name":"Seated Leg Curl (Machine)","sets":3,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0094-bulgarian-split-squat","name":"Bulgarian Split Squat","sets":2,"reps":"8–10","rest_seconds":90,"rpe":7,"section":"main","notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."},{"catalogue_id":"exercise-0679-standing-calf-raise-machine","name":"Standing Calf Raise (Machine)","sets":3,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0068-bird-dog-pas-koji-trazi-prticicu","name":"Bird Dog (Pas koji traži prtičicu)","sets":2,"reps":"8","rest_seconds":45,"rpe":6,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."}]}]},"bs":{"name":"Fokus na donji dio · 2 dana","description":"Dva treninga nogu kao dio postojećeg uravnoteženog rasporeda. Dodajte pregledane treninge gornjeg dijela; ovo nije sedmica za cijelo tijelo.\n\nPonavljajte prikazanu sedmicu. Počnite donjim brojem ponavljanja uz 3–4 ponavljanja u rezervi (RPE 6–7). Dodajte po jedno kontrolisano ponavljanje u seriji; kada sve serije dostignu gornju granicu, dodajte najmanje dostupno opterećenje i vratite se donjoj. Ne povećavajte istovremeno opterećenje i broj serija. Ako oporavak ili tehnika oslabe, ponovite prethodnu sedmicu ili uklonite jednu seriju.\n\nOriginalni opći primjer za odrasle, bez individualne procjene. Prvo pregledajte vježbe i opremu. Počnite laganim probnim serijama; stanite kod bola ili lošeg osjećaja. Ostavite odmor između težih treninga. Prilagodite plan ili zatražite stručni savjet ako zdravlje, trudnoća ili povreda utiču na vježbanje.","weeks":6,"days":[{"title":"A · Donji dio","exercises":[{"catalogue_id":"exercise-0035-back-squat-cucanj-sa-sipkom","name":"Back Squat (Čučanj sa šipkom)","sets":3,"reps":"6–10","rest_seconds":180,"rpe":7,"section":"main","notes":"Po potrebi koristite stalak s pravilno postavljenim osiguračima ili sposobnog pomagača. Prije radnih serija uradite lakše probne serije."},{"catalogue_id":"exercise-0549-romanian-deadlift","name":"Romanian Deadlift","sets":3,"reps":"8–10","rest_seconds":150,"rpe":7,"section":"main","notes":"Po potrebi koristite stalak s pravilno postavljenim osiguračima ili sposobnog pomagača. Prije radnih serija uradite lakše probne serije."},{"catalogue_id":"exercise-0392-leg-extension-machine","name":"Leg Extension (Machine)","sets":2,"reps":"10–15","rest_seconds":75,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0575-seated-calf-raise","name":"Seated Calf Raise","sets":3,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"8–10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."}]},{"title":"B · Donji dio","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":3,"reps":"10–12","rest_seconds":120,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0582-seated-leg-curl-machine","name":"Seated Leg Curl (Machine)","sets":3,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0094-bulgarian-split-squat","name":"Bulgarian Split Squat","sets":2,"reps":"8–10","rest_seconds":90,"rpe":7,"section":"main","notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."},{"catalogue_id":"exercise-0679-standing-calf-raise-machine","name":"Standing Calf Raise (Machine)","sets":3,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0068-bird-dog-pas-koji-trazi-prticicu","name":"Bird Dog (Pas koji traži prtičicu)","sets":2,"reps":"8","rest_seconds":45,"rpe":6,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."}]}]},"de":{"name":"Unterkörper-Fokus · 2 Tage","description":"Zwei Beineinheiten als Teil eines ausgewogenen Plans. Geprüfte Oberkörpereinheiten ergänzen; dies ist keine Ganzkörperwoche.\n\nDie angegebene Woche wiederholen. Am unteren Ende des Wiederholungsbereichs mit 3–4 Wiederholungen Reserve (RPE 6–7) beginnen. Bei guter Kontrolle eine Wiederholung pro Satz ergänzen; erreichen alle Sätze die Obergrenze, das kleinste verfügbare Gewicht hinzufügen und unten beginnen. Gewicht und Satzzahl nicht gleichzeitig erhöhen. Bei schlechterer Erholung oder Technik die Vorwoche wiederholen oder einen Satz streichen.\n\nEin eigenes allgemeines Beispiel für Erwachsene ohne individuelle Untersuchung. Übungen und Geräte zuerst prüfen. Mit leichten Übungssätzen beginnen; bei Schmerzen oder Unwohlsein stoppen. Zwischen schweren Einheiten Erholung einplanen. Bei gesundheitlichen Einschränkungen, Schwangerschaft oder Verletzung anpassen oder fachlichen Rat einholen.","weeks":6,"days":[{"title":"A · Unterkörper","exercises":[{"catalogue_id":"exercise-0035-back-squat-cucanj-sa-sipkom","name":"Back Squat (Čučanj sa šipkom)","sets":3,"reps":"6–10","rest_seconds":180,"rpe":7,"section":"main","notes":"Bei Bedarf ein Rack mit passend eingestellten Sicherungen oder eine erfahrene Hilfsperson nutzen. Vor den Arbeitssätzen mit leichteren Übungssätzen aufwärmen."},{"catalogue_id":"exercise-0549-romanian-deadlift","name":"Romanian Deadlift","sets":3,"reps":"8–10","rest_seconds":150,"rpe":7,"section":"main","notes":"Bei Bedarf ein Rack mit passend eingestellten Sicherungen oder eine erfahrene Hilfsperson nutzen. Vor den Arbeitssätzen mit leichteren Übungssätzen aufwärmen."},{"catalogue_id":"exercise-0392-leg-extension-machine","name":"Leg Extension (Machine)","sets":2,"reps":"10–15","rest_seconds":75,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0575-seated-calf-raise","name":"Seated Calf Raise","sets":3,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"8–10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."}]},{"title":"B · Unterkörper","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":3,"reps":"10–12","rest_seconds":120,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0582-seated-leg-curl-machine","name":"Seated Leg Curl (Machine)","sets":3,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0094-bulgarian-split-squat","name":"Bulgarian Split Squat","sets":2,"reps":"8–10","rest_seconds":90,"rpe":7,"section":"main","notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."},{"catalogue_id":"exercise-0679-standing-calf-raise-machine","name":"Standing Calf Raise (Machine)","sets":3,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0068-bird-dog-pas-koji-trazi-prticicu","name":"Bird Dog (Pas koji traži prtičicu)","sets":2,"reps":"8","rest_seconds":45,"rpe":6,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."}]}]}}'::jsonb),
('kinra-upper-focus','training',1,'{"en":{"name":"Upper-body focus · 2 days","description":"Two complementary push/pull sessions for an existing balanced schedule. Add reviewed lower-body work.\n\nRepeat the listed week. Begin at the low end of each rep range with 3–4 reps in reserve (RPE 6–7). Add one rep per set when controlled; after every set reaches the top, increase the smallest available load and return to the low end. Do not increase load and sets together. If recovery or form worsens, repeat the previous week or remove one set.\n\nAn original general adult example, not an individually assessed prescription. Review exercises and equipment first. Start with easy practice sets; stop for pain or feeling unwell. Schedule rest between hard sessions. Adjust or seek qualified guidance when health, pregnancy or injury affects exercise.","weeks":6,"days":[{"title":"A · Upper","exercises":[{"catalogue_id":"exercise-0060-bench-press-potisak-s-ravne-klupe","name":"Bench Press (Potisak s ravne klupe)","sets":3,"reps":"6–10","rest_seconds":150,"rpe":7,"section":"main","notes":"Use a rack with correctly set safeties or a competent spotter where needed. Warm up with lighter practice sets before the working sets."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":2,"reps":"8–12","res