econds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0227-dumbbell-lateral-raise","name":"Dumbbell Lateral Raise","sets":2,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0554-rope-triceps-pushdown","name":"Rope Triceps Pushdown","sets":2,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."}]},{"title":"B · Oberkörper","exercises":[{"catalogue_id":"exercise-0330-incline-bench-press-kosi-potisak-gornji-dio-prsa","name":"Incline Bench Press (Kosi potisak — gornji dio prsa)","sets":3,"reps":"8–12","rest_seconds":120,"rpe":7,"section":"main","notes":"Bei Bedarf ein Rack mit passend eingestellten Sicherungen oder eine erfahrene Hilfsperson nutzen. Vor den Arbeitssätzen mit leichteren Übungssätzen aufwärmen."},{"catalogue_id":"exercise-0152-chest-supported-row-veslanje-s-osloncem-na-prsa","name":"Chest Supported Row (Veslanje s osloncem na prsa)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Kontrollierter Bewegu