('kinra-easy-restart','training',1,'{"en":{"name":"Easy restart · 2 days","description":"A small, low-effort starting week for adults returning after an ordinary break. This is not rehabilitation or a post-illness clearance plan.\n\nWeek 1: use one easy set per exercise with about 5 reps in reserve (RPE 5). If comfortable and recovered, use two sets in week 2 and keep them through weeks 3–4. Add reps within the range before adding load. Reassess before moving to a larger routine.\n\nAn original general adult example, not an individually assessed prescription. Review exercises and equipment first. Start with easy practice sets; stop for pain or feeling unwell. Schedule rest between hard sessions. Adjust or seek qualified guidance when health, pregnancy or injury affects exercise.","weeks":4,"days":[{"title":"A · Full body","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":1,"reps":"8–10","rest_seconds":90,"rpe":5,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0266-flat-machine-chest-press-wide-grip","name":"Flat Machine Chest Press (Wide Grip)","sets":1,"reps":"8–10","rest_seconds":90,"rpe":5,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":1,"reps":"8–10","rest_seconds":90,"rpe":5,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":1,"reps":"6","rest_seconds":60,"rpe":5,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."}]},{"title":"B · Full body","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":1,"reps":"8–10","rest_seconds":90,"rpe":5,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":1,"reps":"8–10","rest_seconds":90,"rpe":5,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0364-knee-push-up-skleka-s-koljenima","name":"Knee Push-Up (Skleka s koljenima)","sets":1,"reps":"6–8","rest_seconds":90,"rpe":5,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0282-glute-bridge-most-straznjice","name":"Glute Bridge (Most stražnjice)","sets":1,"reps":"8–10","rest_seconds":60,"rpe":5,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."}]}]},"bs":{"name":"Lagani povratak · 2 dana","description":"Kratka početna sedmica manjeg napora za odrasle nakon uobičajene pauze. Ovo nije rehabilitacija niti plan povratka nakon bolesti.\n\nPrva sedmica: jedna lagana serija uz oko 5 ponavljanja u rezervi (RPE 5). Ako vam odgovara i oporavljeni ste, u drugoj sedmici radite dvije serije i zadržite ih do četvrte. Dodajte ponavljanja unutar raspona prije opterećenja. Ponovo procijenite prije većeg plana.\n\nOriginalni opći primjer za odrasle, bez individualne procjene. Prvo pregledajte vježbe i opremu. Počnite laganim probnim serijama; stanite kod bola ili lošeg osjećaja. Ostavite odmor između težih treninga. Prilagodite plan ili zatražite stručni savjet ako zdravlje, trudnoća ili povreda utiču na vježbanje.","weeks":4,"days":[{"title":"A · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":1,"reps":"8–10","rest_seconds":90,"rpe":5,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0266-flat-machine-chest-press-wide-grip","name":"Flat Machine Chest Press (Wide Grip)","sets":1,"reps":"8–10","rest_seconds":90,"rpe":5,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":1,"reps":"8–10","rest_seconds":90,"rpe":5,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":1,"reps":"6","rest_seconds":60,"rpe":5,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."}]},{"title":"B · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":1,"reps":"8–10","rest_seconds":90,"rpe":5,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":1,"reps":"8–10","rest_seconds":90,"rpe":5,"section":"main","notes":"Krećite se kontrolisano i dišite ravnomjerno. Odaberite opterećenje s rezervom prema zadanom naporu."},{"catalogue_id":"exercise-0364-knee-push-up-skleka-s-koljenima","name":"Knee Push-Up (Skleka s koljenima)","sets":1,"reps":"6–8","rest_seconds":90,"rpe":5,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0282-glute-bridge-most-straznjice","name":"Glute Bridge (Most stražnjice)","sets":1,"reps":"8–10","rest_seconds":60,"rpe":5,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."}]}]},"de":{"name":"Leichter Wiedereinstieg · 2 Tage","description":"Eine kleine Einstiegswoche mit geringer Anstrengung nach einer gewöhnlichen Pause. Kein Rehabilitations- oder Freigabeplan nach Krankheit.\n\nWoche 1: ein leichter Satz je Übung mit etwa 5 Wiederholungen Reserve (RPE 5). Bei guter Verträglichkeit und Erholung ab Woche 2 zwei Sätze bis Woche 4. Zuerst Wiederholungen im Bereich, dann Gewicht ergänzen. Vor einem größeren Plan neu bewerten.\n\nEin eigenes allgemeines Beispiel für Erwachsene ohne individuelle Untersuchung. Übungen und Geräte zuerst prüfen. Mit leichten Übungssätzen beginnen; bei Schmerzen oder Unwohlsein stoppen. Zwischen schweren Einheiten Erholung einplanen. Bei gesundheitlichen Einschränkungen, Schwangerschaft oder Verletzung anpassen oder fachlichen Rat einholen.","weeks":4,"days":[{"title":"A · Ganzkörper","exercises":[{"catalogue_id":"exercise-0393-leg-press-potisak-nogama","name":"Leg Press (Potisak nogama)","sets":1,"reps":"8–10","rest_seconds":90,"rpe":5,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0266-flat-machine-chest-press-wide-grip","name":"Flat Machine Chest Press (Wide Grip)","sets":1,"reps":"8–10","rest_seconds":90,"rpe":5,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":1,"reps":"8–10","rest_seconds":90,"rpe":5,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":1,"reps":"6","rest_seconds":60,"rpe":5,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."}]},{"title":"B · Ganzkörper","exercises":[{"catalogue_id":"exercise-0284-goblet-squat","name":"Goblet Squat","sets":1,"reps":"8–10","rest_seconds":90,"rpe":5,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":1,"reps":"8–10","rest_seconds":90,"rpe":5,"section":"main","notes":"Kontrollierter Bewegungsumfang und gleichmäßig atmen. Eine Last mit der vorgesehenen Belastungsreserve wählen."},{"catalogue_id":"exercise-0364-knee-push-up-skleka-s-koljenima","name":"Knee Push-Up (Skleka s koljenima)","sets":1,"reps":"6–8","rest_seconds":90,"rpe":5,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0282-glute-bridge-most-straznjice","name":"Glute Bridge (Most stražnjice)","sets":1,"reps":"8–10","rest_seconds":60,"rpe":5,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."}]}]}}'::jsonb),
('kinra-bodyweight-build','training',1,'{"en":{"name":"Bodyweight build · 3 days","description":"Three sessions for adults comfortable with floor push-ups. Includes a rated fixed bar for rows and a stable low step.\n\nRepeat the week with a rest day between sessions. Add one controlled rep per set up to the upper limit. Then use a slightly harder movement variation only after reviewing it, and restart at the lower limit. Keep 2–4 reps in reserve; extra speed is not progression.\n\nAn original general adult example, not an individually assessed prescription. Review exercises and equipment first. Start with easy practice sets; stop for pain or feeling unwell. Schedule rest between hard sessions. Adjust or seek qualified guidance when health, pregnancy or injury affects exercise. Use only a purpose-built, load-rated fixed bar for rows. Review mounting and body position before training; never substitute a table or loose furniture.","weeks":6,"days":[{"title":"A · Full body","exercises":[{"catalogue_id":"exercise-0507-push-up-skleka","name":"Push-Up (Skleka)","sets":3,"reps":"8–15","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0345-inverted-row-obrnuto-veslanje-ispod-precke","name":"Inverted Row (Obrnuto veslanje — ispod prečke)","sets":3,"reps":"6–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0542-reverse-lunge-iskorak-unazad","name":"Reverse Lunge (Iskorak unazad)","sets":3,"reps":"10–12","rest_seconds":75,"rpe":7,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."}]},{"title":"B · Full body","exercises":[{"catalogue_id":"exercise-0691-step-up-korak-na-klupe-stepenice","name":"Step-Up (Korak na klupe/stepenice)","sets":3,"reps":"8–12","rest_seconds":75,"rpe":7,"section":"main","weight":0,"notes":"Use a low, stable step. Reps are per leg; complete both legs for one set. Do not use an unstable chair."},{"catalogue_id":"exercise-0462-pike-push-up-skleka-u-v-poziciji","name":"Pike Push-Up (Skleka u V poziciji)","sets":2,"reps":"5–10","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0345-inverted-row-obrnuto-veslanje-ispod-precke","name":"Inverted Row (Obrnuto veslanje — ispod prečke)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0633-single-leg-glute-bridge-jednonozni-most","name":"Single-Leg Glute Bridge (Jednonožni most)","sets":3,"reps":"10–12","rest_seconds":60,"rpe":7,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."}]},{"title":"C · Full body","exercises":[{"catalogue_id":"exercise-0507-push-up-skleka","name":"Push-Up (Skleka)","sets":3,"reps":"8–15","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0345-inverted-row-obrnuto-veslanje-ispod-precke","name":"Inverted Row (Obrnuto veslanje — ispod prečke)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0071-bodyweight-squat-cucanj-s-tjelesnom-tezinom","name":"Bodyweight Squat (Čučanj s tjelesnom težinom)","sets":3,"reps":"15–20","rest_seconds":60,"rpe":7,"section":"main","weight":0,"notes":"Bodyweight is the intended resistance; use a stable surface and a comfortable range. Stop before technique changes."},{"catalogue_id":"exercise-0068-bird-dog-pas-koji-trazi-prticicu","name":"Bird Dog (Pas koji traži prtičicu)","sets":2,"reps":"10","rest_seconds":45,"rpe":6,"section":"main","weight":0,"notes":"Reps are per side. Complete both sides for one set; match the easier side and rest after both."}]}]},"bs":{"name":"Napredak vlastitom težinom · 3 dana","description":"Tri treninga za odrasle koji sigurno rade sklekove na podu. Potrebna je čvrsto postavljena prečka za veslanje i niska stabilna stepenica.\n\nPonavljajte sedmicu uz dan odmora između treninga. Dodajte po jedno kontrolisano ponavljanje do gornje granice. Zatim, tek nakon pregleda, odaberite malo težu varijantu i počnite donjim brojem. Zadržite 2–4 ponavljanja u rezervi; veća brzina nije napredak.\n\nOriginalni opći primjer za odrasle, bez individualne procjene. Prvo pregledajte vježbe i opremu. Počnite laganim probnim serijama; stanite kod bola ili lošeg osjećaja. Ostavite odmor između težih treninga. Prilagodite plan ili zatražite stručni savjet ako zdravlje, trudnoća ili povreda utiču na vježbanje. Za veslanje koristite samo namjensku čvrstu prečku odgovarajuće nosivosti. Provjerite montažu i položaj tijela; ne koristite sto ili labav namještaj.","weeks":6,"days":[{"title":"A · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0507-push-up-skleka","name":"Push-Up (Skleka)","sets":3,"reps":"8–15","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0345-inverted-row-obrnuto-veslanje-ispod-precke","name":"Inverted Row (Obrnuto veslanje — ispod prečke)","sets":3,"reps":"6–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0542-reverse-lunge-iskorak-unazad","name":"Reverse Lunge (Iskorak unazad)","sets":3,"reps":"10–12","rest_seconds":75,"rpe":7,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."}]},{"title":"B · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0691-step-up-korak-na-klupe-stepenice","name":"Step-Up (Korak na klupe/stepenice)","sets":3,"reps":"8–12","rest_seconds":75,"rpe":7,"section":"main","weight":0,"notes":"Koristite nisku, stabilnu stepenicu. Ponavljanja su po nozi; obje noge čine jednu seriju. Ne koristite nestabilnu stolicu."},{"catalogue_id":"exercise-0462-pike-push-up-skleka-u-v-poziciji","name":"Pike Push-Up (Skleka u V poziciji)","sets":2,"reps":"5–10","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0345-inverted-row-obrnuto-veslanje-ispod-precke","name":"Inverted Row (Obrnuto veslanje — ispod prečke)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0633-single-leg-glute-bridge-jednonozni-most","name":"Single-Leg Glute Bridge (Jednonožni most)","sets":3,"reps":"10–12","rest_seconds":60,"rpe":7,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."}]},{"title":"C · Cijelo tijelo","exercises":[{"catalogue_id":"exercise-0507-push-up-skleka","name":"Push-Up (Skleka)","sets":3,"reps":"8–15","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0345-inverted-row-obrnuto-veslanje-ispod-precke","name":"Inverted Row (Obrnuto veslanje — ispod prečke)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0071-bodyweight-squat-cucanj-s-tjelesnom-tezinom","name":"Bodyweight Squat (Čučanj s tjelesnom težinom)","sets":3,"reps":"15–20","rest_seconds":60,"rpe":7,"section":"main","weight":0,"notes":"Otpor je vlastita tjelesna težina; koristite stabilnu podlogu i ugodan opseg. Stanite prije promjene tehnike."},{"catalogue_id":"exercise-0068-bird-dog-pas-koji-trazi-prticicu","name":"Bird Dog (Pas koji traži prtičicu)","sets":2,"reps":"10","rest_seconds":45,"rpe":6,"section":"main","weight":0,"notes":"Ponavljanja su po strani. Obje strane čine jednu seriju; pratite slabiju stranu i odmorite nakon obje."}]}]},"de":{"name":"Körpergewicht-Aufbau · 3 Tage","description":"Drei Einheiten für Erwachsene mit sicherem Liegestütz am Boden. Mit belastbarer fester Ruderstange und stabiler niedriger Stufe.\n\nDie Woche mit einem Ruhetag zwischen Einheiten wiederholen. Kontrollierte Wiederholungen bis zur Obergrenze ergänzen. Danach erst nach Prüfung eine etwas schwierigere Variante wählen und unten beginnen. 2–4 Wiederholungen Reserve lassen; höheres Tempo ist kein Fortschrittskriterium.\n\nEin eigenes allgemeines Beispiel für Erwachsene ohne individuelle Untersuchung. Übungen und Geräte zuerst prüfen. Mit leichten Übungssätzen beginnen; bei Schmerzen oder Unwohlsein stoppen. Zwischen schweren Einheiten Erholung einplanen. Bei gesundheitlichen Einschränkungen, Schwangerschaft oder Verletzung anpassen oder fachlichen Rat einholen. Für Rudern nur eine dafür vorgesehene, belastbare feste Stange verwenden. Montage und Körperposition prüfen; keinen Tisch oder lose Möbel ersetzen.","weeks":6,"days":[{"title":"A · Ganzkörper","exercises":[{"catalogue_id":"exercise-0507-push-up-skleka","name":"Push-Up (Skleka)","sets":3,"reps":"8–15","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0345-inverted-row-obrnuto-veslanje-ispod-precke","name":"Inverted Row (Obrnuto veslanje — ispod prečke)","sets":3,"reps":"6–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0542-reverse-lunge-iskorak-unazad","name":"Reverse Lunge (Iskorak unazad)","sets":3,"reps":"10–12","rest_seconds":75,"rpe":7,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."},{"catalogue_id":"exercise-0185-dead-bug-mrtva-buba","name":"Dead Bug (Mrtva buba)","sets":2,"reps":"10","rest_seconds":60,"rpe":6,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."}]},{"title":"B · Ganzkörper","exercises":[{"catalogue_id":"exercise-0691-step-up-korak-na-klupe-stepenice","name":"Step-Up (Korak na klupe/stepenice)","sets":3,"reps":"8–12","rest_seconds":75,"rpe":7,"section":"main","weight":0,"notes":"Eine niedrige, stabile Stufe nutzen. Wiederholungen pro Bein; beide Beine ergeben einen Satz. Keinen instabilen Stuhl verwenden."},{"catalogue_id":"exercise-0462-pike-push-up-skleka-u-v-poziciji","name":"Pike Push-Up (Skleka u V poziciji)","sets":2,"reps":"5–10","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0345-inverted-row-obrnuto-veslanje-ispod-precke","name":"Inverted Row (Obrnuto veslanje — ispod prečke)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0633-single-leg-glute-bridge-jednonozni-most","name":"Single-Leg Glute Bridge (Jednonožni most)","sets":3,"reps":"10–12","rest_seconds":60,"rpe":7,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."}]},{"title":"C · Ganzkörper","exercises":[{"catalogue_id":"exercise-0507-push-up-skleka","name":"Push-Up (Skleka)","sets":3,"reps":"8–15","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0345-inverted-row-obrnuto-veslanje-ispod-precke","name":"Inverted Row (Obrnuto veslanje — ispod prečke)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0071-bodyweight-squat-cucanj-s-tjelesnom-tezinom","name":"Bodyweight Squat (Čučanj s tjelesnom težinom)","sets":3,"reps":"15–20","rest_seconds":60,"rpe":7,"section":"main","weight":0,"notes":"Das eigene Körpergewicht ist der Widerstand; eine stabile Fläche und angenehmen Umfang nutzen. Vor Technikverlust stoppen."},{"catalogue_id":"exercise-0068-bird-dog-pas-koji-trazi-prticicu","name":"Bird Dog (Pas koji traži prtičicu)","sets":2,"reps":"10","rest_seconds":45,"rpe":6,"section":"main","weight":0,"notes":"Wiederholungen pro Seite. Beide Seiten ergeben einen Satz; an der schwächeren Seite orientieren und danach pausieren."}]}]}}'::jsonb),
